package app.studyhub.domain; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue private UUID id; @Column(unique=true,nullable=false) private String email; @Column(nullable=false) private String passwordHash; @Column(nullable=false) private String role="ROLE_USER"; private String name; @Column(nullable=false) private boolean enabled = true; private String verificationCode; private java.time.LocalDateTime verificationCodeExpires; public UUID getId(){return id;} public String getEmail(){return email;} public void setEmail(String email){this.email=email;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String passwordHash){this.passwordHash=passwordHash;} public String getRole(){return role;} public String getName(){return name;} public void setName(String name){this.name=name;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean enabled){this.enabled=enabled;} public String getVerificationCode(){return verificationCode;} public void setVerificationCode(String verificationCode){this.verificationCode=verificationCode;} public java.time.LocalDateTime getVerificationCodeExpires(){return verificationCodeExpires;} public void setVerificationCodeExpires(java.time.LocalDateTime verificationCodeExpires){this.verificationCodeExpires=verificationCodeExpires;} }
